const userPermissions = `-- name: UserPermissions :many
SELECT DISTINCT rp.permission_key
FROM user_roles ur
JOIN role_permissions rp ON rp.role_key = ur.role_key
WHERE ur.user_id = $1 AND ur.scope_type IS NULL
ORDER BY rp.permission_key
`

// Global permissions: the union over the user's unscoped roles.
func (q *Queries) UserPermissions(ctx context.Context, userID string) ([]string, error) {
	rows, err := q.db.Query(ctx, userPermissions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var permission_key string
		if err := rows.Scan(&permission_key); err != nil {
			return nil, err
		}
		items = append(items, permission_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const userRoles = `-- name: UserRoles :many

SELECT role_key FROM user_roles WHERE user_id = $1 AND scope_type IS NULL ORDER BY role_key
`

// ---------------------------------------------------------------- RBAC
// Global (unscoped) roles only.
func (q *Queries) UserRoles(ctx context.Context, userID string) ([]string, error) {
	rows, err := q.db.Query(ctx, userRoles, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var role_key string
		if err := rows.Scan(&role_key); err != nil {
			return nil, err
		}
		items = append(items, role_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
